import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { motion } from 'framer-motion';
import toast from 'react-hot-toast';

const Navbar = () => {
  const navigate = useNavigate();
  const { user, logout } = useAuth();
  const { darkMode, toggleDarkMode } = useTheme();

  const handleLogout = () => {
    logout();
    toast.success('Logged out successfully');
    navigate('/login');
  };

  return (
    <motion.nav 
      initial={{ y: -50, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.5 }}
      style={{
        background: darkMode ? 'rgba(10, 10, 30, 0.95)' : 'rgba(255, 255, 255, 0.95)',
        backdropFilter: 'blur(10px)',
        padding: '12px 30px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        borderBottom: darkMode ? '1px solid rgba(255,255,255,0.1)' : '1px solid rgba(0,0,0,0.08)',
        position: 'sticky',
        top: 0,
        zIndex: 1000,
        boxShadow: darkMode ? '0 4px 30px rgba(0,0,0,0.3)' : '0 4px 30px rgba(0,0,0,0.08)',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: '10px', cursor: 'pointer' }} onClick={() => navigate('/')}>
        <span style={{ fontSize: '28px' }}>⚡</span>
        <h1 style={{ 
          fontSize: '24px', 
          fontWeight: 800,
          background: 'linear-gradient(135deg, #6c63ff, #ff6b6b)',
          WebkitBackgroundClip: 'text',
          WebkitTextFillColor: 'transparent',
        }}>
          CodeArena
        </h1>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
        <button
          onClick={toggleDarkMode}
          style={{
            background: 'none',
            border: 'none',
            fontSize: '20px',
            cursor: 'pointer',
            padding: '8px',
            borderRadius: '50%',
            transition: 'all 0.3s',
          }}
        >
          {darkMode ? '☀️' : '🌙'}
        </button>

        {user && (
          <>
            <button 
              onClick={() => navigate('/problems')}
              style={{
                padding: '8px 20px',
                background: darkMode ? 'rgba(108, 99, 255, 0.2)' : '#6c63ff',
                color: darkMode ? '#6c63ff' : 'white',
                border: darkMode ? '1px solid #6c63ff' : 'none',
                borderRadius: '8px',
                cursor: 'pointer',
                fontWeight: 500,
                transition: 'all 0.3s',
              }}
            >
              📚 Problems
            </button>
            <button 
              onClick={() => navigate('/submissions')}
              style={{
                padding: '8px 20px',
                background: 'transparent',
                color: darkMode ? '#aaa' : '#666',
                border: 'none',
                borderRadius: '8px',
                cursor: 'pointer',
                fontWeight: 500,
                transition: 'all 0.3s',
              }}
            >
              📊 Submissions
            </button>
            {(user?.role === 'admin' || user?.role === 'setter') && (
              <button 
                onClick={() => navigate('/create-problem')}
                style={{
                  padding: '8px 20px',
                  background: '#4CAF50',
                  color: 'white',
                  border: 'none',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  fontWeight: 500,
                }}
              >
                ➕ Create
              </button>
            )}
            <div style={{ 
              display: 'flex', 
              alignItems: 'center', 
              gap: '10px',
              paddingLeft: '15px',
              borderLeft: darkMode ? '1px solid rgba(255,255,255,0.1)' : '1px solid rgba(0,0,0,0.1)',
            }}>
              <span style={{ fontSize: '14px', color: darkMode ? '#aaa' : '#666' }}>
                👤 {user?.username}
              </span>
              <button 
                onClick={handleLogout}
                style={{
                  padding: '6px 16px',
                  background: '#f44336',
                  color: 'white',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontSize: '13px',
                  fontWeight: 500,
                  transition: 'all 0.3s',
                }}
              >
                Logout
              </button>
            </div>
          </>
        )}
      </div>
    </motion.nav>
  );
};

export default Navbar;
